const resp = $input.first().json || {};
const hits = (resp.hits && Array.isArray(resp.hits.hits)) ? resp.hits.hits : [];
const out = [];

for (const hit of hits.slice(0, 15)) {
  const src = hit._source || {};
  const displayNames = Array.isArray(src.display_names) ? src.display_names : [];
  const rawName = String(displayNames[0] || src.entity || '').replace(/\s*\(CIK[^)]*\)/i, '').trim();
  if (!rawName) continue;
  const slug = rawName.toLowerCase().replace(/\b(inc|llc|corp|corporation|ltd|lp|fund|partners)\b/g, '').replace(/[^a-z0-9]+/g, '');
  if (!slug || slug.length < 3) continue;
  out.push({
    json: {
      companyName: rawName,
      inferredDomain: `${slug}.com`,
      signalType: 'SEC_FORM_D',
      formDDate: String(src.file_date || ''),
      cik: Array.isArray(src.ciks) ? String(src.ciks[0] || '') : '',
      openRolesCount: 0,
      opsRolesCount: 0
    }
  });
}
return out.length ? out : [{ json: { companyName: 'No Recent Form D Hits', inferredDomain: '', signalType: 'SEC_FORM_D_EMPTY', openRolesCount: 0, opsRolesCount: 0 } }];

const cfg = $input.first().json || {};
const splitSlugs = (v) => String(v || '').split(',').map((s) => s.trim().toLowerCase()).filter((s) => /^[a-z0-9-]+$/.test(s));
const jobs = [];

for (const slug of splitSlugs(cfg.greenhouseSlugs)) {
  jobs.push({ json: { atsProvider: 'greenhouse', slug, companyName: slug, inferredDomain: `${slug}.com`, apiUrl: `https://boards-api.greenhouse.io/v1/boards/${slug}/jobs` } });
}
for (const slug of splitSlugs(cfg.leverSlugs)) {
  jobs.push({ json: { atsProvider: 'lever', slug, companyName: slug, inferredDomain: `${slug}.com`, apiUrl: `https://api.lever.co/v0/postings/${slug}?mode=json` } });
}
for (const slug of splitSlugs(cfg.ashbySlugs)) {
  jobs.push({ json: { atsProvider: 'ashby', slug, companyName: slug, inferredDomain: `${slug}.app`, apiUrl: `https://api.ashbyhq.com/posting-api/job-board/${slug}` } });
}
return jobs;

const respItems = $input.all();
const metaItems = $items('Expand Public ATS Board URLs');
const rolePattern = /(revops|growth|automation|operations|ai engineer|data engineer|gtm)/i;
const out = [];

for (let i = 0; i < respItems.length; i += 1) {
  const body = respItems[i].json;
  const meta = (metaItems[i] && metaItems[i].json) ? metaItems[i].json : {};
  let list = [];
  if (Array.isArray(body)) {
    list = body;
  } else if (body && Array.isArray(body.jobs)) {
    list = body.jobs;
  }
  const opsCount = list.filter((j) => rolePattern.test(String(j.title || j.text || ''))).length;
  out.push({
    json: {
      companyName: meta.companyName || meta.slug || 'Unknown',
      inferredDomain: meta.inferredDomain || '',
      signalType: `ATS_${String(meta.atsProvider || 'board').toUpperCase()}`,
      formDDate: '',
      cik: '',
      openRolesCount: list.length,
      opsRolesCount: opsCount
    }
  });
}
return out;

const probes = $input.all();
const leads = $items('Merge Funding & Hiring Signals');
const enriched = [];

for (let i = 0; i < leads.length; i += 1) {
  const lead = leads[i].json || {};
  if (!lead.inferredDomain) continue;
  const probe = (probes[i] && probes[i].json) ? probes[i].json : {};
  const statusCode = Number(probe.statusCode || 0);
  const bodyStr = typeof probe.body === 'string' ? probe.body : '';
  const llmsPresent = statusCode === 200 && bodyStr.length >= 80 && !/<html/i.test(bodyStr.slice(0, 300));

  let score = 0;
  if (lead.signalType === 'SEC_FORM_D') score += 45;
  if (lead.openRolesCount >= 10) score += 25;
  else if (lead.openRolesCount >= 3) score += 15;
  if (lead.opsRolesCount >= 1) score += 15;
  if (!llmsPresent) score += 20;
  score = Math.min(100, score);

  const hook = !llmsPresent
    ? `Missing /llms.txt (HTTP ${statusCode || 'ERR'}) while actively scaling (${lead.signalType})` 
    : `Active ${lead.signalType} growth signal (${lead.openRolesCount} open roles)`;

  enriched.push({
    json: {
      ...lead,
      llmsStatusCode: statusCode,
      llmsPresent,
      icpScore: score,
      isHotLead: score >= 65,
      outreachHook: hook,
      evaluatedAtUtc: new Date().toISOString()
    }
  });
}
return enriched;
